"""
Self-extracting package bootstrap & entrypoint for NAPSSIEC.
Works whether Render runs:
  1) `python app.py`
  2) `uvicorn app.main:app --host 0.0.0.0 --port $PORT`
"""
import os
import sys
import io
import zipfile
import base64
import importlib

_ROOT_DIR = os.path.dirname(os.path.abspath(__file__))
_APP_DIR = os.path.join(_ROOT_DIR, "app")

_BUNDLE_B64 = ""

_EXTRACTED = False

def _ensure_app_extracted():
    global _EXTRACTED
    if not _EXTRACTED:
        raw = base64.b64decode(_BUNDLE_B64)
        with zipfile.ZipFile(io.BytesIO(raw), "r") as zf:
            zf.extractall(_ROOT_DIR)
        _EXTRACTED = True

_ensure_app_extracted()

# Mark this module as a package pointing to the './app' directory
__path__ = [_APP_DIR]

if __name__ == "__main__":
    import uvicorn
    # Register current module as 'app' package so relative imports inside app/ work
    sys.modules["app"] = sys.modules[__name__]
    main_mod = importlib.import_module("app.main")
    port = int(os.environ.get("PORT", 8000))
    uvicorn.run(main_mod.app, host="0.0.0.0", port=port)
